"""Generate the locale tables from the PostgreSQL 18.6 C.UTF-8 oracle."""

import csv
from collections import defaultdict
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
ORACLE = ROOT / "upstream" / "oracle"


def rows(name):
    with (ORACLE / name).open(encoding="ascii", newline="") as source:
        yield from csv.reader(source)


def main():
    classes = defaultdict(list)
    for name, start, end in rows("classes.csv"):
        classes[name].append((int(start), int(end)))

    output = [
        "// Generated by tools/gen_ctype.py from upstream/oracle. Do not edit.",
        "",
    ]
    for name, ranges in sorted(classes.items()):
        declaration = f"pub(super) const {name.upper()}: &[(u32, u32)] = "
        entries = [f"({start}, {end})" for start, end in ranges]
        if len(entries) <= 3:
            output.extend((declaration + "&[" + ", ".join(entries) + "];", ""))
        else:
            output.append(declaration + "&[")
            output.extend(f"    {entry}," for entry in entries)
            output.extend(("];", ""))

    output.append("pub(super) const CASE: &[(u32, u32, u32)] = &[")
    output.extend(f"    ({int(cp)}, {int(upper)}, {int(lower)})," for cp, upper, lower in rows("case.csv"))
    output.append("];")
    (ROOT / "src" / "engine" / "ctype_tables.rs").write_text(
        "\n".join(output) + "\n", encoding="ascii", newline="\n"
    )


if __name__ == "__main__":
    main()
